style.css:
@-moz-document domain("classroom.google.com") {
/* Set the background to a GIF */
  body {
    background: url('https://media3.giphy.com/media/v1.Y2lkPTc5MGI3NjExaGF2cjMwcjlkaXhocHM3cGlnZmdmeWQ5bmplbmtlcmhleTVoOXY0NiZlcD12MV9pbnRlcm5hbF9naWZfYnlfaWQmY3Q9Zw/2BEavB3PIFHZS/giphy.gif') no-repeat center center fixed !important;
    background-size: cover !important;
    font-family: 'Poppins', sans-serif !important; /* Apply Poppins font */
  }

  /* Header Styling */
  header {
    background-color: rgba(0, 123, 255, 0.7) !important; /* Light blue background with opacity */
    color: white !important;
    font-family: 'Poppins', sans-serif !important;
  }

  /* Links and header text color */
  header a, header h1 {
    color: white !important;
  }

  /* Sidebar Styling */
  .XkIi4c {
    background-color: rgba(255, 255, 255, 0.8) !important; /* Transparent white */
    border-right: 2px solid #ddd !important;
  }

  .XkIi4c a {
    color: #007BFF !important; /* Light blue color for links */
  }

  .XkIi4c a:hover {
    color: #0056b3 !important; /* Darker blue on hover */
  }

  /* Cards and Assignments Styling */
  .Qxs5wf, .Jd5nLe {
    background-color: rgba(255, 255, 255, 0.9) !important;
    border-radius: 8px !important;
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1) !important;
  }

  /* Baby Pink and Baby Blue Button Styling */
  .aYp1O, .M9QdP, .s9VZ5e {
    background-color: #FFB6C1 !important; /* Baby Pink */
    color: white !important;
    border: none !important;
    border-radius: 4px !important;
    padding: 8px 16px !important;
    font-family: 'Poppins', sans-serif !important; /* Cute font for buttons */
    font-weight: bold;
  }

  .aYp1O:hover, .M9QdP:hover, .s9VZ5e:hover {
    background-color: #BFEFFF !important; /* Baby Blue */
    color: white !important;
  }

  /* Button Focus Effect */
  .aYp1O:focus, .M9QdP:focus, .s9VZ5e:focus {
    background-color: #BFEFFF !important; /* Baby Blue */
    color: white !important;
  }

  /* Text Color */
  .kSgwc, .Fxtnn, .t8Pwnc {
    color: #333333 !important;
  }

  /* Class Cards Hover Effect */
  .eP5e8d:hover {
    transform: scale(1.05);
    transition: transform 0.3s ease;
  }
}
